const b = $json.body ?? $json;
function required(name){const v=b[name]; if(v===undefined||v===null||String(v).trim()==='') throw new Error(`Missing required field: ${name}`); return String(v).trim();}
const name=required('name'); const email=required('email').toLowerCase(); const phone=required('phone'); const address=required('address'); const service=required('service'); const date=required('date'); const time=required('time'); const durationMinutes=Number(b.durationMinutes||120);
if(!/^\S+@\S+\.\S+$/.test(email)) throw new Error('Invalid email');
if(!/^\d{4}-\d{2}-\d{2}$/.test(date)) throw new Error('Invalid date format');
if(!/^\d{2}:\d{2}$/.test(time)) throw new Error('Invalid time format');
const start=new Date(`${date}T${time}:00`); if(Number.isNaN(start.getTime())) throw new Error('Invalid booking datetime'); const end=new Date(start.getTime()+durationMinutes*60000); const bookingId=`CLN-${Date.now()}-${Math.floor(Math.random()*900+100)}`;
return [{json:{bookingId,name,email,phone,address,service,notes:String(b.notes||'').trim(),start:start.toISOString(),end:end.toISOString(),durationMinutes,status:'PENDING',createdAt:new Date().toISOString()}}];

